const CACHE='qiaoqiao-island-four-2';
const FILES=['./','./index.html','./style.css','./main.js','./world.js','./rewards.js','./curriculum.js','./adventure.js','./feedback.js','./catch.html','./catch.css','./catch.js','./catch-game.js','./catch-world.js','./journey.html','./journey.css','./journey.js','./journey-game.js','./journey-store.js','./journey-stone-world.js','./room-world.js','./room-scene.js','./mail-world.js','./stone.html','./stone.css','./stone.js','./stone-game.js','./stone-world.js','./stone-island.js','./favicon.svg','./vendor/three.module.js','./vendor/three.core.js','./vendor/BufferGeometryUtils.js'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(async cache=>{for(const file of FILES){const response=await fetch(file,{cache:'reload'});if(!response.ok||response.redirected)throw new Error('Offline asset unavailable');await cache.put(file,response);}await self.skipWaiting();}));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('qiaoqiao-island-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;const base=new URL('./',self.location).pathname;if(event.request.mode==='navigate'){event.respondWith(fetch(event.request).then(async response=>{if(response.ok&&!response.redirected&&(url.pathname===base||url.pathname===base+'index.html')){const cache=await caches.open(CACHE);await cache.put('./index.html',response.clone());}return response;}).catch(async()=>await caches.match(event.request,{ignoreSearch:true})||await caches.match('./index.html')||await caches.match('./')));return;}if(!FILES.some(file=>new URL(file,self.location).pathname===url.pathname))return;event.respondWith(caches.match(event.request).then(cached=>cached||fetch(event.request)));});
